// must compare the coefficients, allowing for exponents
// compare the adjusted exponents first, as their difference may not fit
// in an Int [the exponent may be as low as -1999999997 and as high as
// 999999999, so the difference can exceed the range of Int]
{
  Long ae_lhs=(Long)lhs->exponent+lhs->digits; // adjusted exponent
  Long ae_rhs=(Long)rhs->exponent+rhs->digits; // ..
  if (ae_lhs>ae_rhs) return result;
  if (ae_lhs<ae_rhs) return -result;
  }
// here the adjusted exponents are equal, so the exponent difference is
// bounded by the difference of the digit counts and fits in an Int
if (lhs->exponent>rhs->exponent) {         // LHS exponent larger
  // swap sides, and sign
  const decNumber *temp=lhs;
  lhs=rhs;
  rhs=temp;
  result=-result;
  }
compare=decUnitCompare(lhs->lsu, D2U(lhs->digits),
                       rhs->lsu, D2U(rhs->digits),
                       rhs->exponent-lhs->exponent);

